const body = $input.first().json.body || {};
return [{ json: {
  docId: 'cRP1WgZQv7KmwmVrUbuEF8',
  userId: Number(body.userId),
  action: (body.action || 'status').toString(),
  useKey: body.useKey === true,
  today: new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris' }).format(new Date())
} }];

const cfg = $('Set Config').first().json;
const users = $('Get Users').all().map((i) => i.json).filter((r) => r.id != null);
const user = users.find((u) => u.id === cfg.userId);
if (!user) return [{ json: { ok: false, error: 'user_not_found' } }];

function toDateStr(v) { if (v == null) return null; if (typeof v === "number") return new Date(v * 1000).toISOString().slice(0, 10); return String(v).slice(0, 10); }
const alreadySpun = toDateStr(user.LastWheelSpinDate) === cfg.today;

if (cfg.action === 'status') {
  return [{ json: { ok: true, docId: cfg.docId, userId: cfg.userId, canSpin: !alreadySpun, keys: user.KeyCount || 0, shouldUpdate: false } }];
}

// Relance payante (2026-10-02) : une fois le tirage gratuit du jour utilise,
// le cadenas de la roue permet de la relancer contre 1 clef secrete.
let keyCost = 0;
if (alreadySpun) {
  if (!cfg.useKey) return [{ json: { ok: false, error: 'already_spun' } }];
  if ((user.KeyCount || 0) < 1) return [{ json: { ok: false, error: 'no_key' } }];
  keyCost = 1;
}

// Mix prudent : surtout de la poussiere, jamais de carte directe (pas de
// raccourci vers les raretes fortes via la roue). Enrichi le 2026-09-30 :
// une clef secrete (meme monnaie que la fouille/le coffre-fort) et un rare
// palier "jackpot" (boosters + grosse poussiere d'un coup) en plus des 3
// paliers d'origine.
const roll = Math.random();
let prize;
if (roll < 0.50) prize = { type: 'stardust', amount: 10 + Math.floor(Math.random() * 16), tier: 'small' };
else if (roll < 0.70) prize = { type: 'stardust', amount: 50 + Math.floor(Math.random() * 51), tier: 'big' };
else if (roll < 0.85) prize = { type: 'booster', amount: 1, tier: 'booster' };
else if (roll < 0.95) prize = { type: 'key', amount: 1, tier: 'key' };
else prize = { type: 'jackpot', amount: 2, dust: 100, tier: 'jackpot' };

const dustGained = prize.type === 'stardust' ? prize.amount : (prize.type === 'jackpot' ? prize.dust : 0);
const boostersFromPrize = prize.type === 'booster' ? prize.amount : (prize.type === 'jackpot' ? prize.amount : 0);
const keysFromPrize = prize.type === 'key' ? prize.amount : 0;
const newStardust = (user.StardustCount || 0) + dustGained;
const newKeyCount = (user.KeyCount || 0) - keyCost + keysFromPrize;

// Niveaux de profil : XP gagnee en tournant la roue, +1 booster bonus par
// niveau franchi (en plus du lot de la roue elle-meme).
function levelForXp(xp) { xp = xp || 0; return Math.floor((25 + Math.sqrt(625 + 100 * xp)) / 50); }
const XP_PER_WHEEL_SPIN = 5;
const newXp = (user.XP || 0) + XP_PER_WHEEL_SPIN;
const levelsGained = levelForXp(newXp) - levelForXp(user.XP || 0);
const newBoosterCount = (user.BoosterCount || 0) + boostersFromPrize + levelsGained;

return [{ json: {
  ok: true, docId: cfg.docId, userId: cfg.userId, today: cfg.today,
  shouldUpdate: true, canSpin: false, prize, newStardust, newBoosterCount, newKeyCount, newXp
} }];

function levelForXp(xp) { xp = xp || 0; return Math.floor((25 + Math.sqrt(625 + 100 * xp)) / 50); }
const r = $('Compute Result').first().json;
if (r.prize) return [{ json: { canSpin: false, prize: r.prize, newStardust: r.newStardust, newBoosterCount: r.newBoosterCount, newKeyCount: r.newKeyCount, xp: { total: r.newXp, level: levelForXp(r.newXp) } } }];
return [{ json: { canSpin: r.canSpin, keys: r.keys || 0 } }];
